insert into public.courses (slug, name_en, name_fr, description_en, description_fr, short_description_en, short_description_fr, price, currency, thumbnail_url) values ($icb$world-stage$icb$, $icb$World Stage$icb$, $icb$World Stage$icb$, $icb$World Stage is a private, 12-month communication mentorship for senior leaders who operate in complex, high-stakes environments. It helps you communicate with greater clarity, influence and composure — so you can lead more effectively and contribute to a more stable, cooperative world.$icb$, $icb$World Stage est un mentorat privé de 12 mois en communication pour les dirigeants qui évoluent dans des environnements complexes et à forts enjeux. Il vous aide à communiquer avec plus de clarté, d'influence et de calme, afin de diriger plus efficacement et de contribuer à un monde plus stable et plus coopératif.$icb$, $icb$Your passport to walking into meetings, presentations and negotiations in English feeling comfortable with your own skin just as you do in French, using the techniques and wisdom Roger discovered and used during his years of meditation and self-discovery$icb$, $icb$Votre passeport pour entrer en réunion, en présentation et en négociation en anglais aussi à l'aise que vous l'êtes en français, grâce aux techniques et à l'expérience que Roger a découvertes et utilisées pendant ses années de méditation et de connaissance de soi.$icb$, 10000, $icb$USD$icb$, $icb$/images/world-stage-book.png$icb$);
insert into public.course_modules (course_id, position, title_en, title_fr, description_en, description_fr) select id, 1, $icb$Onboarding & baseline$icb$, $icb$Intégration et point de départ$icb$, $icb$We start with a deep dive into your background, goals, key communication context, establishing a clear baseline and success metrics$icb$, $icb$Nous commençons par votre parcours, vos objectifs et votre contexte, pour fixer un point de départ et des critères de réussite.$icb$ from public.courses where slug = $icb$world-stage$icb$;
insert into public.course_modules (course_id, position, title_en, title_fr, description_en, description_fr) select id, 2, $icb$Internal repositioning$icb$, $icb$Repositionnement intérieur$icb$, $icb$We work on mindset, presence, narrative, aligning how you see yourself with how you need to be perceived$icb$, $icb$Nous travaillons l'état d'esprit, la présence et le récit, pour aligner votre image sur la perception attendue.$icb$ from public.courses where slug = $icb$world-stage$icb$;
insert into public.course_modules (course_id, position, title_en, title_fr, description_en, description_fr) select id, 3, $icb$Communication architecture$icb$, $icb$Architecture du message$icb$, $icb$We build a clear, dependable framework for your key messages, tailored to different audiences and situations$icb$, $icb$Nous construisons un cadre clair pour vos messages essentiels, adapté aux publics et aux situations.$icb$ from public.courses where slug = $icb$world-stage$icb$;
insert into public.course_modules (course_id, position, title_en, title_fr, description_en, description_fr) select id, 4, $icb$Rehearsed performance$icb$, $icb$Performance répétée$icb$, $icb$You practice in realistic, high-pressure scenarios, with personalized feedback to sharpen your delivery and composure$icb$, $icb$Vous vous exercez dans des situations réalistes et tendues, avec un retour personnalisé sur votre voix et votre calme.$icb$ from public.courses where slug = $icb$world-stage$icb$;
insert into public.course_modules (course_id, position, title_en, title_fr, description_en, description_fr) select id, 5, $icb$International proof$icb$, $icb$Preuve internationale$icb$, $icb$We apply your skills in real-world settings, from international meetings to media appearances, with visible progress within 2–3 months$icb$, $icb$Nous mettons vos acquis en situation réelle, des réunions internationales aux médias, avec des progrès visibles en 2 à 3 mois.$icb$ from public.courses where slug = $icb$world-stage$icb$;
insert into public.course_modules (course_id, position, title_en, title_fr, description_en, description_fr) select id, 6, $icb$Continuity & independence$icb$, $icb$Continuité et autonomie$icb$, $icb$We ensure the gains last, with a tailored plan, ongoing resources and the confidence to thrive long after the program$icb$, $icb$Nous faisons durer les acquis, avec un plan adapté, des ressources et l'assurance de continuer après le programme.$icb$ from public.courses where slug = $icb$world-stage$icb$;
insert into public.courses (slug, name_en, name_fr, description_en, description_fr, short_description_en, short_description_fr, price, currency, thumbnail_url) values ($icb$global-fluency$icb$, $icb$Global Fluency$icb$, $icb$Global Fluency$icb$, $icb$It's simple. In this program you get work with Roger, who is a software engineer, inventor and entrepreneur. He grew up in rural francophone Africa and rose to the world stage through self-reliance. He acquire English and Spanish through unconventional methods mostly for his own desire to have a seat on world stage. And today he share just that with hundreds of corporate leaders from around the world who simply can't afford to be viewed as a second class citizen in front of their international peers$icb$, $icb$C'est simple. Dans ce programme, vous travaillez avec Roger, ingénieur logiciel, inventeur et entrepreneur. Il a grandi dans une zone rurale d'Afrique francophone et a atteint la scène mondiale par lui-même. Il a appris l'anglais et l'espagnol par des méthodes peu conventionnelles, surtout pour prendre place sur cette scène. Aujourd'hui, il transmet cela à des centaines de dirigeants qui ne peuvent pas se permettre d'être perçus comme des interlocuteurs de second rang face à leurs pairs internationaux.$icb$, $icb$The ultimate system to reaching in months the natural fluency you've been dreaming about for years and now entering the company or position that has always been out of your reach$icb$, $icb$Le système pour atteindre en quelques mois l'aisance naturelle dont vous rêvez depuis des années, et accéder enfin à l'entreprise ou au poste qui vous échappait.$icb$, 500, $icb$USD$icb$, $icb$/images/global-fluency-book.png$icb$);
insert into public.course_modules (course_id, position, title_en, title_fr, description_en, description_fr) select id, 1, $icb$Self-image shift$icb$, $icb$Changement d'image de soi$icb$, $icb$The solution to our problems lay not in books or trainings but in our own minds. You are abrilliant person in your field already more difficult than English, why would English be difficult for you, to the point of even blocking your progress?$icb$, $icb$La solution à nos difficultés ne se trouve pas dans les livres ou les formations, mais dans notre propre esprit. Vous êtes déjà brillant dans un domaine plus difficile que l'anglais : pourquoi l'anglais vous bloquerait-il au point d'arrêter votre progression ?$icb$ from public.courses where slug = $icb$global-fluency$icb$;
insert into public.course_modules (course_id, position, title_en, title_fr, description_en, description_fr) select id, 2, $icb$Understanding native accents$icb$, $icb$Comprendre les accents natifs$icb$, $icb$The solution to our problems lay not in books or trainings but in our own minds. You are abrilliant person in your field already more difficult than English, why would English be difficult for you, to the point of even blocking your progress?$icb$, $icb$La solution à nos difficultés ne se trouve pas dans les livres ou les formations, mais dans notre propre esprit. Vous êtes déjà brillant dans un domaine plus difficile que l'anglais : pourquoi l'anglais vous bloquerait-il au point d'arrêter votre progression ?$icb$ from public.courses where slug = $icb$global-fluency$icb$;
insert into public.course_modules (course_id, position, title_en, title_fr, description_en, description_fr) select id, 3, $icb$Achieving native level speaking$icb$, $icb$Parler au niveau natif$icb$, $icb$The solution to our problems lay not in books or trainings but in our own minds. You are abrilliant person in your field already more difficult than English, why would English be difficult for you, to the point of even blocking your progress?$icb$, $icb$La solution à nos difficultés ne se trouve pas dans les livres ou les formations, mais dans notre propre esprit. Vous êtes déjà brillant dans un domaine plus difficile que l'anglais : pourquoi l'anglais vous bloquerait-il au point d'arrêter votre progression ?$icb$ from public.courses where slug = $icb$global-fluency$icb$;
insert into public.course_modules (course_id, position, title_en, title_fr, description_en, description_fr) select id, 4, $icb$12-month private mentorship$icb$, $icb$Mentorat privé de 12 mois$icb$, $icb$The solution to our problems lay not in books or trainings but in our own minds. You are abrilliant person in your field already more difficult than English, why would English be difficult for you, to the point of even blocking your progress?$icb$, $icb$La solution à nos difficultés ne se trouve pas dans les livres ou les formations, mais dans notre propre esprit. Vous êtes déjà brillant dans un domaine plus difficile que l'anglais : pourquoi l'anglais vous bloquerait-il au point d'arrêter votre progression ?$icb$ from public.courses where slug = $icb$global-fluency$icb$;
insert into public.news (slug, title_en, title_fr, summary_en, summary_fr, image_url, is_published, type) values ($icb$black-friday-sale$icb$, $icb$Black Friday Sale!$icb$, $icb$Vente du Black Friday !$icb$, $icb$And on thios Friday we’re going to sell everything off for no money and I mean$icb$ || chr(10) || $icb$absolutely no money.  In this short video, Roger explains the mission behind$icb$ || chr(10) || $icb$world stage, who it is for, and what you can expect  an here is what we’re going$icb$ || chr(10) || $icb$to do to succeed$icb$, $icb$Ce vendredi, tout part, et je dis bien$icb$ || chr(10) || $icb$pour rien. Dans cette courte vidéo, Roger explique la mission$icb$ || chr(10) || $icb$de World Stage, à qui elle s'adresse, et ce que nous allons$icb$ || chr(10) || $icb$mettre en place pour réussir.$icb$, $icb$/images/news-black-friday.png$icb$, true, $icb$promotion$icb$);
